-- Seed bilingual demo recipes from resource_temp CSV pair.

delete from public.recipes where slug in ('cedar-planked-salmon-2f32ec', 'instant-pot-vegan-15-bean-soup-ee8318', 'shortbread-crust-f23df2', 'tzatziki-chicken-naan-pizza-e271eb', 'sweet-salty-spicy-party-nuts-fe11c2', 'chef-john-s-irish-soda-bread-c58a69', 'pickled-garlic-7e42b1', 'caramel-candies-7dba49', 'turkey-in-a-bag-3ac9dc', 'baked-sweet-potato-fries-243e70', 'easy-peach-cobbler-with-cake-mix-232236', 'bacon-wrapped-stuffed-mushrooms-f68362', 'sloppy-joe-sandwich-filling-7c8037', 'country-fried-potatoes-with-hatch-chiles-4546e8', 'marinated-mushrooms-ea9d1b', 'delicious-grilled-hamburgers-83a962', 'parmesan-crusted-chicken-fd9fcd', 'hot-toddy-cocktail-30f8a5', 'chocolate-apple-egg-rolls-98eee7', 'famous-meatballs-1ac332');

on conflict (id) do update set name = excluded.name, default_unit = excluded.default_unit, category = excluded.category;

on conflict (ingredient_id, locale) do update set name = excluded.name;





on conflict (recipe_id, ingredient_id) do update set amount = excluded.amount, unit = excluded.unit;

on conflict (recipe_id, technique_id) do update set is_primary = excluded.is_primary;
