insert into public.recipes (id, slug, name, description, difficulty, estimated_minutes, servings, required_tools, category, subcategory) values
('e795df5b-29dd-4a14-899a-2ad444557098', 'cedar-planked-salmon-2f32ec', 'Cedar Planked Salmon', 'This cedar plank salmon is a dish my brother prepared for me in Seattle. The salmon is moist, smoky, and by far the best I''ve ever eaten. I like to serve it with Asian-style rice and asparagus.', 3, 35, 2, ARRAY['그릴']::text[], 'Picnic Recipes', 'Memorial Day Recipes'),
('dc789361-abc2-4ad0-8c2d-6848c363d822', 'instant-pot-vegan-15-bean-soup-ee8318', 'Instant Pot Vegan 15-Bean Soup', 'This 15-bean Instant Pot soup is a vegan version of the popular soup. Hearty and rich, this tasty soup is the perfect comfort food and so easy to make in your Instant Pot.', 3, 63, 2, ARRAY['냄비', '칼']::text[], 'Low Fat', 'Low-Fat Soups And Stews'),
('fda5ed6b-5443-4e95-870f-b31f4f70fb1e', 'shortbread-crust-f23df2', 'Shortbread Crust', 'Simple and easy shortbread crust you''ll love. Especially wonderful if your planning to make a peach pie.', 1, 14, 2, ARRAY['오븐', '믹서']::text[], 'Pies', 'Pie Crusts'),
('d6c5b0f3-468b-4138-8fff-f8705296370f', 'tzatziki-chicken-naan-pizza-e271eb', 'Tzatziki Chicken Naan Pizza', 'This tzatziki chicken naan pizza is a quick prep that will make you feel like you''re at the pub. Naan is topped with tzatziki, chicken, and feta, then baked until melty and scattered with fresh tomatoes, cucumber, and red onion.', 3, 7, 2, ARRAY['오븐']::text[], 'Italian', 'Pizza'),
('92d142f9-c7ac-40ca-8781-c6bf3a1845c3', 'sweet-salty-spicy-party-nuts-fe11c2', 'Sweet, Salty, Spicy Party Nuts', 'This spiced nuts recipe is made using a much easier technique than the stovetop pan method. You''ll get beautiful, perfectly frosted nuts roasted evenly, with no bitter burned spots.', 3, 11, 2, ARRAY['오븐', '냄비']::text[], 'Christmas', 'Food Gifts'),
('87e4d3c7-d12a-485e-8860-fb512658c003', 'chef-john-s-irish-soda-bread-c58a69', 'Chef John''s Irish Soda Bread', 'This soda bread recipe is a great way to celebrate St. Patrick''s Day, which is right around the corner! If made correctly, this is one of the best quick breads (those leavened without yeast) you''ll ever have. It''s subtly sweet, with a light, tender crumb, and not at all dry.', 4, 60, 2, ARRAY['오븐', '칼', '믹서']::text[], 'Irish Soda Bread', 'Irish Soda Bread'),
('a718dac1-1a20-48e7-8aa4-ed46931174a5', 'pickled-garlic-7e42b1', 'Pickled Garlic', 'These pickled garlic cloves take a long time, but they''re easy to make and are a real treat.', 2, 10, 2, ARRAY['냄비']::text[], 'Pickles', 'Pickled Vegetables'),
('a4b2b6ef-2009-49bf-831a-b5d20c596116', 'caramel-candies-7dba49', 'Caramel Candies', 'These caramels are made with brown sugar, cream, butter and corn syrup and flavored with a hint of vanilla.', 2, 10, 2, ARRAY['냄비']::text[], 'Desserts', 'Caramel Desserts'),
('6aef55de-21c9-4ffc-8031-04861f43ef59', 'turkey-in-a-bag-3ac9dc', 'Turkey in a Bag', 'Cooking turkey in a bag is easy with this recipe. Your Thanksgiving turkey will be perfectly moist when done, and you can make gravy out of the juice that forms in the bottom of the bag. Plus, cleanup is a snap! The cooking time will vary if your turkey is larger or smaller than 12 pounds.', 2, 60, 2, ARRAY['오븐']::text[], 'Main Dishes', 'Fall Main Dishes'),
('819ee4f8-3dcf-494f-8985-34941c91cfef', 'baked-sweet-potato-fries-243e70', 'Baked Sweet Potato Fries', 'These sweet potato fries make a great side dish and are sure to please your friends and family. Season as you please!', 2, 26, 2, ARRAY['오븐', '냄비']::text[], 'Fries', 'Fries'),
('5673899d-521d-434e-85e5-dad8069c7238', 'easy-peach-cobbler-with-cake-mix-232236', 'Easy Peach Cobbler with Cake Mix', 'This fresh peach cobbler with cake mix is so simple, yet it wins rave reviews. It''s a quick but company-worthy cobbler.', 2, 45, 2, ARRAY['오븐', '칼']::text[], 'Labor Day', 'Labor Day Desserts'),
('dc361a3f-ad32-4560-89c5-07df0408fff0', 'bacon-wrapped-stuffed-mushrooms-f68362', 'Bacon Wrapped Stuffed Mushrooms', 'A classic favorite stuffed mushroom is taken to new heights by wrapping in a slice of bacon. Simple, but will melt in your mouth!', 1, 20, 2, ARRAY['오븐', '칼']::text[], 'Appetizers And Snacks', 'Stuffed Mushrooms'),
('1a2e6b5f-9f7c-4f28-86ca-dda622fdadee', 'sloppy-joe-sandwich-filling-7c8037', 'Sloppy Joe Sandwich Filling', 'The traditional sloppy Joe goes south of the border in this tangy, flavorful sandwich filling.', 4, 16, 2, ARRAY['프라이팬']::text[], 'Ground Beef', 'Sloppy Joes'),
('9b8e2e2e-ab38-4732-80af-01b90a7dc244', 'country-fried-potatoes-with-hatch-chiles-4546e8', 'Country Fried Potatoes with Hatch Chiles', 'Spice up your life and kick up your breakfast potatoes a notch by adding Hatch chiles. I used fresh-frozen charred Hatch chiles, but you can use canned if fresh are not in season.', 2, 30, 2, ARRAY['냄비', '프라이팬', '칼']::text[], 'Cooking For Two', 'Cooking Breakfast For Two'),
('0e588b9a-f3bf-4e19-86e3-577dc92b149b', 'marinated-mushrooms-ea9d1b', 'Marinated Mushrooms', 'Little mushrooms are marinated in a zesty mixture and are great for buffet-style gatherings. This recipe was handed down to me by my grandma. They keep well for a long time in the fridge, or you may can them in mason jars and store them in the cupboard.', 3, 11, 2, ARRAY['냄비']::text[], 'Labor Day', 'Labor Day Appetizers'),
('bf02feae-f857-4476-8943-26b640af9d31', 'delicious-grilled-hamburgers-83a962', 'Delicious Grilled Hamburgers', 'These grilled burgers are tender and juicy with a smoky flavor. Serve on buns with your favorite toppings.', 2, 5, 2, ARRAY['그릴']::text[], 'July 4Th', '4Th Of July Main Dishes'),
('e1cbf24e-ee1a-4d37-84b8-64e6a2690d80', 'parmesan-crusted-chicken-fd9fcd', 'Parmesan Crusted Chicken', 'This Parmesan-crusted chicken with mayo is the simplest and most savory way to dress up chicken breasts for a quick supper. Just top them with mayonnaise, sprinkle with Parmesan cheese and bread crumbs, and bake. Dinner will be ready in 30 minutes or less!', 1, 20, 2, ARRAY['오븐']::text[], 'Dinner', 'Baked And Roasted Chicken'),
('1f480694-8dd1-49b1-8816-3fc842ba3f95', 'hot-toddy-cocktail-30f8a5', 'Hot Toddy Cocktail', 'The hot toddy cocktail is a classic winter warmer. Truth be told, it''s good any time of year and works particularly well if you''re battling a cold.', 1, 12, 2, '{}'::text[], 'Cocktails', 'Whiskey Drinks'),
('efc3ca15-8ddb-4667-8314-0fb194e241fa', 'chocolate-apple-egg-rolls-98eee7', 'Chocolate-Apple Egg Rolls', 'Fry up dessert eggrolls with sweet Golden Delicious apple and Nutella filing. To avoid soggy egg rolls, be sure to let the filling cool completely before assembling.', 4, 8, 2, ARRAY['오븐', '냄비', '프라이팬', '믹서']::text[], 'Desserts', 'Chocolate Desserts'),
('d996ae72-200a-49ac-8985-3c511cf6ba38', 'famous-meatballs-1ac332', 'Famous Meatballs', 'These pineapple meatballs are a favorite for any occasion. I made 14 pounds of meatballs for my sister''s graduation party, and I only had 1 medium container left. My mother made sloppy joes, and needless to say, they had a lot of leftovers because everyone loved these meatballs. Guaranteed favorite!', 2, 40, 2, ARRAY['냄비']::text[], 'Appetizers And Snacks', 'Meatball Appetizers');
insert into public.recipe_translations (recipe_id, locale, name, description, category, subcategory) values
('e795df5b-29dd-4a14-899a-2ad444557098', 'en', 'Cedar Planked Salmon', 'This cedar plank salmon is a dish my brother prepared for me in Seattle. The salmon is moist, smoky, and by far the best I''ve ever eaten. I like to serve it with Asian-style rice and asparagus.', 'Picnic Recipes', 'Memorial Day Recipes'),
('e795df5b-29dd-4a14-899a-2ad444557098', 'ko', '삼나무 판자 연어 구이', '이 삼나무 판자 연어는 시애틀에서 제 남동생이 준비해준 요리입니다. 연어가 촉촉하고 스모키하며, 제가 먹어본 것 중 단연 최고입니다. 아시안 스타일 밥과 아스파라거스와 함께 곁들이는 것을 좋아합니다.', '피크닉 요리법', '현충일 요리법'),
('dc789361-abc2-4ad0-8c2d-6848c363d822', 'en', 'Instant Pot Vegan 15-Bean Soup', 'This 15-bean Instant Pot soup is a vegan version of the popular soup. Hearty and rich, this tasty soup is the perfect comfort food and so easy to make in your Instant Pot.', 'Low Fat', 'Low-Fat Soups And Stews'),
('dc789361-abc2-4ad0-8c2d-6848c363d822', 'ko', '인스턴트 팟 비건 15가지 콩 수프', '이 15가지 콩 인스턴트 팟 수프는 인기 있는 수프의 비건 버전입니다. 풍성하고 진한 이 맛있는 수프는 완벽한 편안한 음식이며 인스턴트 팟으로 만들기 매우 쉽습니다.', '저지방', '저지방 수프와 스튜'),
('fda5ed6b-5443-4e95-870f-b31f4f70fb1e', 'en', 'Shortbread Crust', 'Simple and easy shortbread crust you''ll love. Especially wonderful if your planning to make a peach pie.', 'Pies', 'Pie Crusts'),
('fda5ed6b-5443-4e95-870f-b31f4f70fb1e', 'ko', '쇼트브레드 크러스트', '간단하고 쉬운 쇼트브레드 크러스트로 정말 마음에 드실 거예요. 복숭아 파이를 만들 계획이라면 특히 훌륭합니다.', '파이', '파이 크러스트'),
('d6c5b0f3-468b-4138-8fff-f8705296370f', 'en', 'Tzatziki Chicken Naan Pizza', 'This tzatziki chicken naan pizza is a quick prep that will make you feel like you''re at the pub. Naan is topped with tzatziki, chicken, and feta, then baked until melty and scattered with fresh tomatoes, cucumber, and red onion.', 'Italian', 'Pizza'),
('d6c5b0f3-468b-4138-8fff-f8705296370f', 'ko', '차치키 치킨 난 피자', '이 차치키 치킨 난 피자는 빠르게 준비할 수 있으며 펍에 온 듯한 느낌을 줍니다. 난에 차치키, 치킨, 페타 치즈를 올리고 녹을 때까지 구운 다음 신선한 토마토, 오이, 적양파를 뿌립니다.', '이탈리안', '피자'),
('92d142f9-c7ac-40ca-8781-c6bf3a1845c3', 'en', 'Sweet, Salty, Spicy Party Nuts', 'This spiced nuts recipe is made using a much easier technique than the stovetop pan method. You''ll get beautiful, perfectly frosted nuts roasted evenly, with no bitter burned spots.', 'Christmas', 'Food Gifts'),
('92d142f9-c7ac-40ca-8781-c6bf3a1845c3', 'ko', '달콤하고 짭짤하며 매콤한 파티 넛츠', '이 양념 견과류 레시피는 스토브탑 팬 방식보다 훨씬 쉬운 기법으로 만들어집니다. 쓴맛이 나는 탄 부분 없이 고르게 구워진 아름답고 완벽하게 코팅된 견과류를 얻을 수 있습니다.', '크리스마스', '푸드 선물'),
('87e4d3c7-d12a-485e-8860-fb512658c003', 'en', 'Chef John''s Irish Soda Bread', 'This soda bread recipe is a great way to celebrate St. Patrick''s Day, which is right around the corner! If made correctly, this is one of the best quick breads (those leavened without yeast) you''ll ever have. It''s subtly sweet, with a light, tender crumb, and not at all dry.', 'Irish Soda Bread', 'Irish Soda Bread'),
('87e4d3c7-d12a-485e-8860-fb512658c003', 'ko', '셰프 존의 아이리시 소다 브레드', '이 소다 브레드 레시피는 곧 다가올 성 패트릭의 날을 축하하는 훌륭한 방법입니다! 제대로 만들면 이스트 없이 부풀린 빵 중 최고의 퀵 브레드 중 하나입니다. 은은하게 달콤하고 가볍고 부드러운 속결을 가지고 있으며 전혀 건조하지 않습니다.', '아이리시 소다 브레드', '아이리시 소다 브레드'),
('a718dac1-1a20-48e7-8aa4-ed46931174a5', 'en', 'Pickled Garlic', 'These pickled garlic cloves take a long time, but they''re easy to make and are a real treat.', 'Pickles', 'Pickled Vegetables'),
('a718dac1-1a20-48e7-8aa4-ed46931174a5', 'ko', '피클 마늘', '이 피클 마늘은 시간이 오래 걸리지만 만들기 쉽고 정말 맛있습니다.', '피클', '채소 피클'),
('a4b2b6ef-2009-49bf-831a-b5d20c596116', 'en', 'Caramel Candies', 'These caramels are made with brown sugar, cream, butter and corn syrup and flavored with a hint of vanilla.', 'Desserts', 'Caramel Desserts'),
('a4b2b6ef-2009-49bf-831a-b5d20c596116', 'ko', '캐러멜 캔디', '이 캐러멜은 흑설탕, 크림, 버터, 옥수수 시럽으로 만들어지며 바닐라 향이 은은하게 가미됩니다.', '디저트', '캐러멜 디저트'),
('6aef55de-21c9-4ffc-8031-04861f43ef59', 'en', 'Turkey in a Bag', 'Cooking turkey in a bag is easy with this recipe. Your Thanksgiving turkey will be perfectly moist when done, and you can make gravy out of the juice that forms in the bottom of the bag. Plus, cleanup is a snap! The cooking time will vary if your turkey is larger or smaller than 12 pounds.', 'Main Dishes', 'Fall Main Dishes'),
('6aef55de-21c9-4ffc-8031-04861f43ef59', 'ko', '백에 구운 칠면조', '백에 칠면조를 구우면 이 레시피로 쉽게 만들 수 있습니다. 추수감사절 칠면조가 완벽하게 촉촉하게 익으며, 백 바닥에 고인 육즙으로 그레이비를 만들 수 있습니다. 게다가 뒷정리도 간편합니다! 칠면조가 12파운드보다 크거나 작으면 조리 시간이 달라집니다.', '메인 요리', '가을 메인 요리'),
('819ee4f8-3dcf-494f-8985-34941c91cfef', 'en', 'Baked Sweet Potato Fries', 'These sweet potato fries make a great side dish and are sure to please your friends and family. Season as you please!', 'Fries', 'Fries'),
('819ee4f8-3dcf-494f-8985-34941c91cfef', 'ko', '구운 고구마 튀김', '이 고구마 튀김은 훌륭한 사이드 디시이며 가족과 친구들을 만족시킬 것입니다. 원하는 대로 간을 하세요!', '튀김', '튀김'),
('5673899d-521d-434e-85e5-dad8069c7238', 'en', 'Easy Peach Cobbler with Cake Mix', 'This fresh peach cobbler with cake mix is so simple, yet it wins rave reviews. It''s a quick but company-worthy cobbler.', 'Labor Day', 'Labor Day Desserts'),
('5673899d-521d-434e-85e5-dad8069c7238', 'ko', '케이크 믹스로 만드는 간편 복숭아 코블러', '케이크 믹스를 사용한 이 신선한 복숭아 코블러는 매우 간단하지만 극찬을 받는 레시피입니다. 빠르게 만들 수 있으면서도 손님 대접용으로 손색없는 코블러입니다.', '노동절', '노동절 디저트'),
('dc361a3f-ad32-4560-89c5-07df0408fff0', 'en', 'Bacon Wrapped Stuffed Mushrooms', 'A classic favorite stuffed mushroom is taken to new heights by wrapping in a slice of bacon. Simple, but will melt in your mouth!', 'Appetizers And Snacks', 'Stuffed Mushrooms'),
('dc361a3f-ad32-4560-89c5-07df0408fff0', 'ko', '베이컨 말이 속 채운 버섯', '클래식한 속 채운 버섯 요리에 베이컨 슬라이스를 감싸 새로운 차원으로 끌어올렸습니다. 간단하지만 입에서 살살 녹아요!', '애피타이저와 스낵', '속 채운 버섯'),
('1a2e6b5f-9f7c-4f28-86ca-dda622fdadee', 'en', 'Sloppy Joe Sandwich Filling', 'The traditional sloppy Joe goes south of the border in this tangy, flavorful sandwich filling.', 'Ground Beef', 'Sloppy Joes'),
('1a2e6b5f-9f7c-4f28-86ca-dda622fdadee', 'ko', '슬로피 조 샌드위치 필링', '전통적인 슬로피 조가 멕시코풍으로 변신한 톡 쏘고 풍미 있는 샌드위치 필링입니다.', '간 쇠고기', '슬로피 조'),
('9b8e2e2e-ab38-4732-80af-01b90a7dc244', 'en', 'Country Fried Potatoes with Hatch Chiles', 'Spice up your life and kick up your breakfast potatoes a notch by adding Hatch chiles. I used fresh-frozen charred Hatch chiles, but you can use canned if fresh are not in season.', 'Cooking For Two', 'Cooking Breakfast For Two'),
('9b8e2e2e-ab38-4732-80af-01b90a7dc244', 'ko', '해치 칠리를 곁들인 컨트리 프라이드 포테이토', '해치 칠리를 추가하여 아침 감자 요리를 한층 더 맛있게 만들어보세요. 저는 신선하게 냉동된 구운 해치 칠리를 사용했지만, 제철이 아닐 때는 통조림을 사용하셔도 됩니다.', '2인분 요리', '2인분 아침식사 요리'),
('0e588b9a-f3bf-4e19-86e3-577dc92b149b', 'en', 'Marinated Mushrooms', 'Little mushrooms are marinated in a zesty mixture and are great for buffet-style gatherings. This recipe was handed down to me by my grandma. They keep well for a long time in the fridge, or you may can them in mason jars and store them in the cupboard.', 'Labor Day', 'Labor Day Appetizers'),
('0e588b9a-f3bf-4e19-86e3-577dc92b149b', 'ko', '마리네이드 버섯', '작은 버섯을 풍미 가득한 마리네이드 혼합물에 재워 뷔페 스타일 모임에 훌륭한 요리입니다. 이 레시피는 할머니로부터 물려받았습니다. 냉장고에 오랫동안 보관할 수 있으며, 메이슨 병에 담아 찬장에 보관할 수도 있습니다.', 'Labor Day', 'Labor Day 애피타이저'),
('bf02feae-f857-4476-8943-26b640af9d31', 'en', 'Delicious Grilled Hamburgers', 'These grilled burgers are tender and juicy with a smoky flavor. Serve on buns with your favorite toppings.', 'July 4Th', '4Th Of July Main Dishes'),
('bf02feae-f857-4476-8943-26b640af9d31', 'ko', '맛있는 그릴 햄버거', '이 그릴 버거는 부드럽고 육즙이 풍부하며 스모키한 풍미가 있습니다. 좋아하는 토핑과 함께 번에 올려 드세요.', '7월 4일', '7월 4일 메인 요리'),
('e1cbf24e-ee1a-4d37-84b8-64e6a2690d80', 'en', 'Parmesan Crusted Chicken', 'This Parmesan-crusted chicken with mayo is the simplest and most savory way to dress up chicken breasts for a quick supper. Just top them with mayonnaise, sprinkle with Parmesan cheese and bread crumbs, and bake. Dinner will be ready in 30 minutes or less!', 'Dinner', 'Baked And Roasted Chicken'),
('e1cbf24e-ee1a-4d37-84b8-64e6a2690d80', 'ko', '파마산 크러스트 치킨', '마요네즈를 곁들인 이 파마산 크러스트 치킨은 빠른 저녁 식사를 위해 닭 가슴살을 맛있게 요리하는 가장 간단하고 풍미있는 방법입니다. 마요네즈를 올리고 파마산 치즈와 빵가루를 뿌린 다음 구우면 됩니다. 30분 이내에 저녁 식사가 완성됩니다!', '저녁', '구운 닭고기'),
('1f480694-8dd1-49b1-8816-3fc842ba3f95', 'en', 'Hot Toddy Cocktail', 'The hot toddy cocktail is a classic winter warmer. Truth be told, it''s good any time of year and works particularly well if you''re battling a cold.', 'Cocktails', 'Whiskey Drinks'),
('1f480694-8dd1-49b1-8816-3fc842ba3f95', 'ko', '핫 토디 칵테일', '핫 토디 칵테일은 겨울철 클래식 음료입니다. 사실 일년 내내 좋으며, 감기에 걸렸을 때 특히 효과적입니다.', '칵테일', '위스키 드링크'),
('efc3ca15-8ddb-4667-8314-0fb194e241fa', 'en', 'Chocolate-Apple Egg Rolls', 'Fry up dessert eggrolls with sweet Golden Delicious apple and Nutella filing. To avoid soggy egg rolls, be sure to let the filling cool completely before assembling.', 'Desserts', 'Chocolate Desserts'),
('efc3ca15-8ddb-4667-8314-0fb194e241fa', 'ko', '초콜릿-사과 에그롤', '달콤한 골든 델리셔스 사과와 누텔라 필링으로 디저트 에그롤을 튀겨보세요. 눅눅한 에그롤을 피하려면 필링을 완전히 식힌 후 조립해야 합니다.', '디저트', '초콜릿 디저트'),
('d996ae72-200a-49ac-8985-3c511cf6ba38', 'en', 'Famous Meatballs', 'These pineapple meatballs are a favorite for any occasion. I made 14 pounds of meatballs for my sister''s graduation party, and I only had 1 medium container left. My mother made sloppy joes, and needless to say, they had a lot of leftovers because everyone loved these meatballs. Guaranteed favorite!', 'Appetizers And Snacks', 'Meatball Appetizers'),
('d996ae72-200a-49ac-8985-3c511cf6ba38', 'ko', '유명한 미트볼', '이 파인애플 미트볼은 어떤 행사에도 인기 있는 메뉴입니다. 제 여동생의 졸업 파티를 위해 14파운드의 미트볼을 만들었는데, 중간 크기 용기 하나만 남았습니다. 어머니께서 슬로피 조를 만드셨는데, 말할 것도 없이 모두가 이 미트볼을 너무 좋아해서 슬로피 조는 많이 남았습니다. 확실한 인기 메뉴입니다!', '애피타이저 및 스낵', '미트볼 애피타이저');
insert into public.recipe_steps (id, recipe_id, step_number, instruction) values
('88f65797-7f4e-4db5-8748-3de5f3270537', 'e795df5b-29dd-4a14-899a-2ad444557098', 1, 'Gather all ingredients.'),
('b4a2b7f8-1a20-4f63-8189-cd4dda660dbc', 'e795df5b-29dd-4a14-899a-2ad444557098', 2, 'Soak cedar planks for at least 1 hour in warm water. Soak longer if you have time.'),
('2fb53d46-e2ac-46a1-82f4-91a8f29bb3e0', 'e795df5b-29dd-4a14-899a-2ad444557098', 3, 'Stir soy sauce, vegetable oil, rice vinegar, sesame oil, green onions, ginger, and garlic together in a shallow dish.'),
('f9176c1b-3fb5-43ca-8500-8700e6857bba', 'e795df5b-29dd-4a14-899a-2ad444557098', 4, 'Place salmon fillets in soy mixture and turn to coat. Cover and marinate for at least 15 minutes, or up to 1 hour refrigerated.'),
('a8e2c8a6-05ad-455c-8b8b-b71821180174', 'e795df5b-29dd-4a14-899a-2ad444557098', 5, 'Preheat an outdoor grill for medium heat. Place planks on the grill grate. Heat planks until they start to smoke and crackle just a little.'),
('8d983fae-2167-429d-8b5a-39de0bcf7a60', 'e795df5b-29dd-4a14-899a-2ad444557098', 6, 'Remove salmon from marinade and place on planks; discard marinade.'),
('b992fa8e-f844-440b-8b53-cc32fcd565cf', 'e795df5b-29dd-4a14-899a-2ad444557098', 7, 'Close grill cover. Grill salmon until it flakes easily with a fork, about 20 minutes; salmon will continue to cook after you remove it from the grill.'),
('d73954cb-2ae3-431d-8d61-9b8a93db58e2', 'dc789361-abc2-4ad0-8c2d-6848c363d822', 1, 'Combine vegetable broth, rinsed beans, diced tomatoes, onion, carrots, celery, garlic, sea salt, paprika, and black pepper in a multi-functional pressure cooker (such as Instant Pot). Close and lock the lid. Select high pressure according to manufacturer''s instructions; set the timer for 35 minutes. Allow 10 to 15 minutes for pressure to build.'),
('1e1b50b9-852f-4578-8929-d7c757b55209', 'dc789361-abc2-4ad0-8c2d-6848c363d822', 2, 'Release pressure using the natural-release method according to manufacturer''s instructions, about 10 minutes. Complete releasing pressure carefully using the quick-release method according to manufacturer''s instructions, about 5 minutes. Unlock and remove the lid.'),
('6a738b2f-b792-441f-8e67-1900b4c87963', 'fda5ed6b-5443-4e95-870f-b31f4f70fb1e', 1, 'Preheat oven to 350 degrees F (175 degrees C).'),
('a8e4299f-dc35-498f-8cb2-698737676cc9', 'fda5ed6b-5443-4e95-870f-b31f4f70fb1e', 2, 'In a large bowl, cream butter and confectioners'' sugar until light and fluffy. Stir together flour and baking powder; blend into butter mixture. Pat into a 9 inch pie plate.'),
('5120dddf-6da9-4045-808b-edcc8a54b121', 'fda5ed6b-5443-4e95-870f-b31f4f70fb1e', 3, 'Bake in preheated oven for 12 to 15 minutes, or until edges are lightly browned.'),
('939d311f-9845-4ce5-898a-bc2938b7a2de', 'd6c5b0f3-468b-4138-8fff-f8705296370f', 1, 'Preheat the oven to 350 degrees F (180 degrees C).'),
('cff79f93-4a88-4bcf-8d7a-819d125cb4d1', 'd6c5b0f3-468b-4138-8fff-f8705296370f', 2, 'Place naan breads on a baking sheet; brush each with olive oil. Sprinkle evenly with garlic powder and dried dill. Top each naan with half of tzatziki sauce, 1/2 cup chicken, and half of feta cheese.'),
('dfb6dbe6-3bdb-4df2-8eca-fa7dc2b38d1f', 'd6c5b0f3-468b-4138-8fff-f8705296370f', 3, 'Bake in the preheated oven until cheese is bubbly and the edges are nice and brown, about 7 minutes. Remove from the oven and top with red onion, tomatoes, and cucumber. Serve warm.'),
('5f45abea-119c-4776-8b5c-19e87f0ce61c', '92d142f9-c7ac-40ca-8781-c6bf3a1845c3', 1, 'Gather all ingredients. Preheat the oven to 350 degrees F (175 degrees C). Line a baking sheet with aluminum foil and lightly coat with cooking spray.'),
('73e6c9b7-2eaf-489d-82b6-be6aa9129d0a', '92d142f9-c7ac-40ca-8781-c6bf3a1845c3', 2, 'Combine walnuts, pecans, almonds, and cashews in a large bowl. Add salt, black pepper, cumin, and cayenne; toss to coat.'),
('59d9b1da-ba0d-41a2-8c0b-89c73fc3a69a', '92d142f9-c7ac-40ca-8781-c6bf3a1845c3', 3, 'Heat sugar, water, and butter in a small saucepan over medium heat. Cook until butter is melted and sugar is dissolved, about 1 minute.'),
('a0a852b5-9b84-4af7-87ee-a6b83629a5a8', '92d142f9-c7ac-40ca-8781-c6bf3a1845c3', 4, 'Slowly pour butter mixture over nuts and stir to coat.'),
('00a86926-901a-4415-8aaf-9a730fca44ce', '92d142f9-c7ac-40ca-8781-c6bf3a1845c3', 5, 'Transfer nuts to the prepared baking sheet and spread into a single layer.'),
('597c17b4-464f-4a02-8d88-324cda0283d1', '92d142f9-c7ac-40ca-8781-c6bf3a1845c3', 6, 'Bake nuts in the preheated oven for 10 minutes. Stir nuts to coat with warm syrup; spread out in a single layer. Return to the oven and bake until nuts are sticky and roasted, about 6 more minutes. Allow to cool before serving.'),
('0530fa91-eaf5-4f33-86f7-4cea24784102', '92d142f9-c7ac-40ca-8781-c6bf3a1845c3', 7, 'Allow to cool before serving.'),
('79aeb81d-7833-45de-82e7-c62de7ad6c2f', '87e4d3c7-d12a-485e-8860-fb512658c003', 1, 'Gather all ingredients. Preheat the oven to 375 degrees F (190 degrees C). Line a baking sheet with parchment paper or a silicone baking mat.'),
('8e61bf49-51f8-43f1-8226-ae6a9417b61a', '87e4d3c7-d12a-485e-8860-fb512658c003', 2, 'Whisk all-purpose flour, whole wheat flour, oats, salt, baking soda, and baking powder together in a large bowl. Cut butter into flour mixture using a pastry blender until mixture resembles coarse crumbs.'),
('25ee8413-0489-427e-84a7-85fa45641a7d', '87e4d3c7-d12a-485e-8860-fb512658c003', 3, 'Beat buttermilk, egg, honey, and orange zest together in a medium bowl. Pour buttermilk mixture, currants, and raisins into flour-butter mixture; stir with a wooden spoon until a wet, sticky dough comes together.'),
('25af0307-4e0e-42fd-8056-f77a2252ab27', '87e4d3c7-d12a-485e-8860-fb512658c003', 4, 'Turn dough out onto a well-floured work surface; press dough together into a ball and cut into 2 equal pieces. Form each into a smooth, round loaf.'),
('ace323fa-08ac-4651-80a0-30e62ff57b63', '87e4d3c7-d12a-485e-8860-fb512658c003', 5, 'Transfer to the prepared baking sheet and let rest for 15 minutes. Cut a 1/2-inch-deep "X" into the top of each loaf using a serrated knife.'),
('a46cf066-0a45-4aef-8b51-d3bf32bacbfe', '87e4d3c7-d12a-485e-8860-fb512658c003', 6, 'Bake in the preheated oven until golden brown and fragrant, about 45 minutes. Transfer loaves to a wire rack to cool completely before slicing.'),
('ffb8c320-9d0a-4b84-8516-dd28eba939f2', '87e4d3c7-d12a-485e-8860-fb512658c003', 7, 'Enjoy!'),
('72d49eb6-a1ed-458e-86dc-4aeffefbb562', 'a718dac1-1a20-48e7-8aa4-ed46931174a5', 1, 'Place garlic cloves in a medium bowl, first cutting the large cloves in half. Mix in the red bell pepper.'),
('67bced14-5d75-45c9-862c-3281dbbdab92', 'a718dac1-1a20-48e7-8aa4-ed46931174a5', 2, 'In a large saucepan over medium high heat, place the distilled white vinegar and white sugar. Wrap ground dry mustard and celery seed in a spice bag, and place in the liquid mixture. Bring to a boil. Boil 5 minutes. Stir in garlic and pepper. Continue boiling 5 minutes. Remove from heat and discard spice bag.'),
('d8b7bfb4-78a8-41bf-87e1-0f5abc6c0649', 'a718dac1-1a20-48e7-8aa4-ed46931174a5', 3, 'Place garlic and peppers in sterile containers to within 1 inch of the top. Fill with remaining liquid to within 1/4 inch from the top. Seal and store in the refrigerator approximately three weeks before serving.'),
('39971a06-f72e-4134-8784-42ffd034b74f', 'a4b2b6ef-2009-49bf-831a-b5d20c596116', 1, 'Combine brown sugar, white sugar, butter, corn syrup, cream, milk and vanilla in a medium saucepan over medium heat. Heat, stirring occasionally, to 250 to 265 degrees F (121 to 129 degrees C), or until a small amount of syrup dropped into cold water forms a rigid ball. Pour into an 8x8 inch pan. Let cool before cutting.'),
('901706ea-ca6e-4ed7-8432-b9cb685de294', '6aef55de-21c9-4ffc-8031-04861f43ef59', 1, 'Gather all ingredients.'),
('f3380d15-0133-443c-80ab-2a3b8001e31c', '6aef55de-21c9-4ffc-8031-04861f43ef59', 2, 'Preheat the oven to 350 degrees F (175 degrees C).'),
('125bee52-096f-4006-8e61-9347d83d1ce5', '6aef55de-21c9-4ffc-8031-04861f43ef59', 3, 'Remove and discard giblets.'),
('cd93df6a-347a-4d34-8ea4-489743a410b4', '6aef55de-21c9-4ffc-8031-04861f43ef59', 4, 'Rinse turkey and pat dry.'),
('160c5f82-b48f-4641-892f-4418b09642c9', '6aef55de-21c9-4ffc-8031-04861f43ef59', 5, 'Season turkey with salt and pepper.'),
('96db6a92-9e6d-47cb-8189-1feaeef29307', '6aef55de-21c9-4ffc-8031-04861f43ef59', 6, 'Sprinkle the bottom of the turkey bag with flour.'),
('109345b0-c9b9-4fa4-879f-4405774385c8', '6aef55de-21c9-4ffc-8031-04861f43ef59', 7, 'Place turkey in the bag and add celery and onions.'),
('15153eb5-d1df-45ec-80f9-66736112edda', '6aef55de-21c9-4ffc-8031-04861f43ef59', 8, 'Seal the bag and transfer into a roasting pan; poke several holes in the bag with a fork.'),
('21ea6e5b-2600-4f2c-8cc0-cd9fa7a863d2', '6aef55de-21c9-4ffc-8031-04861f43ef59', 9, 'Bake in the preheated oven until turkey is cooked and the juices run clear, about 3 to 3 1/2 hours. An instant-read thermometer inserted into the thigh meat should read 180 degrees F (85 degrees C).'),
('91c4bd6a-4482-407d-8e64-e8e4bfa1678c', '6aef55de-21c9-4ffc-8031-04861f43ef59', 10, 'Enjoy!'),
('8247e494-6ee7-4d50-88bb-cedaddfdbba1', '819ee4f8-3dcf-494f-8985-34941c91cfef', 1, 'Gather all ingredients.'),
('a8619e92-836a-49a8-8d51-5d39cc4c5667', '819ee4f8-3dcf-494f-8985-34941c91cfef', 2, 'Preheat the oven to 425 degrees F (220 degrees C). Position rack in upper third of the oven. Grease a baking sheet.'),
('c195ee26-3839-4dd9-877c-a272b2a98002', '819ee4f8-3dcf-494f-8985-34941c91cfef', 3, 'Peel sweet potatoes and cut into 1x3-inch wedges. Place wedges and soybean oil in a large bowl; toss lightly. Sprinkle with salt, pepper, garlic powder, and paprika.'),
('7bdd56ab-662a-4fa1-8636-a246ca497515', '819ee4f8-3dcf-494f-8985-34941c91cfef', 4, 'Arrange potatoes in a single layer on the prepared baking sheet, being sure not to overcrowd. Bake, turning occasionally, until tender and golden brown, 18 to 24 minutes. Cool 5 minutes before serving.'),
('8f76469f-a3a0-4a35-8ee5-3949026fa403', '5673899d-521d-434e-85e5-dad8069c7238', 1, 'Preheat the oven to 350 degrees F (175 degrees C).'),
('8f795e48-52b9-4730-8f58-67ac619c3be5', '5673899d-521d-434e-85e5-dad8069c7238', 2, 'Spread peach slices evenly in the bottom of a 9x13-inch baking dish. Stir water and sugar together in a small bowl until dissolved; pour mixture over peaches. Sprinkle cinnamon over peaches, then cake mix. Top cake mix with pats of cream cheese, then butter.'),
('798801b4-362c-4279-8f3e-36a9ca5c9d88', '5673899d-521d-434e-85e5-dad8069c7238', 3, 'Bake in the preheated oven until golden, about 45 minutes.'),
('047755b9-751d-4236-81b1-d08f208be242', 'dc361a3f-ad32-4560-89c5-07df0408fff0', 1, 'Preheat the oven to 350 degrees F (175 degrees C).'),
('98a2922f-2e6a-42d9-81cf-168a3ef5e995', 'dc361a3f-ad32-4560-89c5-07df0408fff0', 2, 'In a medium bowl, mix together the green onions and cream cheese . Stuff mushroom caps with the cheese mixture. Wrap each mushroom with a half-slice of bacon, and secure with toothpicks. Place on a baking sheet.'),
('51346f91-b8b7-4f70-8bf7-ad3db2f14938', 'dc361a3f-ad32-4560-89c5-07df0408fff0', 3, 'Bake for 20 minutes in the preheated oven, until the bacon is cooked through.'),
('d01ae135-83f9-49b0-801f-92425cbc80ea', '1a2e6b5f-9f7c-4f28-86ca-dda622fdadee', 1, 'Melt butter in a skillet over medium heat. Cook onion and poblano pepper until softened, about 5 minutes. Transfer mixture to a plate. Add ground beef and chorizo to the skillet. Cook, stirring often to break up meat, until browned and crumbly, 5 to 7 minutes. Add enchilada seasoning and tomato powder. Add water, ketchup, and Worcestershire sauce. Return cooked onion mixture to the skillet. Simmer until flavors combine, about 5 minutes more.'),
('dc44adc0-c419-4df4-81d2-5f96621386c9', '1a2e6b5f-9f7c-4f28-86ca-dda622fdadee', 2, 'Serve meat mixture on toasted buns topped with Oaxaca cheese and avocado.'),
('9d430237-8b2e-4052-8e95-46c33298306b', '9b8e2e2e-ab38-4732-80af-01b90a7dc244', 1, 'Place Hatch chiles directly on the grates of a gas stove over medium heat. Cook, flipping with tongs occasionally, until blackened and charred, about 5 minutes. Place in a sealed plastic bag and allow to cool, 7 to 8 minutes. Peel off charred skins, remove seeds, and slice chiles.'),
('0fd70de3-e5b3-4407-85c7-020777d64638', '9b8e2e2e-ab38-4732-80af-01b90a7dc244', 2, 'Slice potato using a mandoline.'),
('56357ba9-f9bc-4b54-8884-c6af6dc63dc3', '9b8e2e2e-ab38-4732-80af-01b90a7dc244', 3, 'Heat oil in a large skillet over medium-high heat until shimmering. Add potato slices and fry undisturbed until starting to brown and soften, 8 to 12 minutes. Add onion slices and chiles. Season with seasoned salt and black pepper. Stir to combine. Cook until onions are translucent and potatoes are fully softened and browned on the second side, 5 to 8 minutes.'),
('e5bdd60b-358d-41f4-89ba-5975e78f17c0', '0e588b9a-f3bf-4e19-86e3-577dc92b149b', 1, 'Combine onion, vinegar, olive oil, parsley, brown sugar, garlic, salt, and dry mustard in a medium saucepan. Bring to a boil. Reduce heat, stir in mushrooms, and simmer for 10 to 12 minutes, stirring occasionally.'),
('f521cd76-682d-428a-846d-7b510e8cbe9a', '0e588b9a-f3bf-4e19-86e3-577dc92b149b', 2, 'Transfer mushroom mixture to sterile containers and chill in the refrigerator until serving.'),
('c489fcce-b3a3-4698-80c3-5582a9e4f279', 'bf02feae-f857-4476-8943-26b640af9d31', 1, 'Gather the ingredients.'),
('74b31868-70b3-4202-8d6b-45ed04192745', 'bf02feae-f857-4476-8943-26b640af9d31', 2, 'Preheat an outdoor grill for high heat and lightly oil the grate.'),
('14f24990-3483-4663-806e-17243d5f4816', 'bf02feae-f857-4476-8943-26b640af9d31', 3, 'Combine ground beef, Worcestershire sauce, liquid smoke, and garlic powder in a medium bowl; lightly mix until just combined.'),
('30258334-092b-426c-89bd-163dbb4e4b31', 'bf02feae-f857-4476-8943-26b640af9d31', 4, 'With minimal handling, form mixture into three patties.'),
('2017b9bf-8012-4ca5-85b7-1328330701cc', 'bf02feae-f857-4476-8943-26b640af9d31', 5, 'Brush oil onto both sides of each patty, then season with salt.'),
('c83c3bb2-b7df-4a29-8fb0-db3a5d986221', 'bf02feae-f857-4476-8943-26b640af9d31', 6, 'Cook patties on the preheated grill until no longer pink in the center, about 5 minutes per side. An instant-read thermometer inserted into the center should read at least 160 degrees F (70 degrees C).'),
('7ed33c9a-bf75-4ede-8931-90fc220f4f4d', 'e1cbf24e-ee1a-4d37-84b8-64e6a2690d80', 1, 'Gather all ingredients. Preheat the oven to 425 degrees F (220 degrees C).'),
('a1b16812-e004-4ef2-81a6-e62e85798f8a', 'e1cbf24e-ee1a-4d37-84b8-64e6a2690d80', 2, 'Mix mayonnaise and Parmesan cheese together in a medium bowl until well combined.'),
('6b199f73-2c4d-4533-8966-9971e95ff250', 'e1cbf24e-ee1a-4d37-84b8-64e6a2690d80', 3, 'Arrange chicken breasts on a baking sheet. Evenly top with mayonnaise mixture, then sprinkle with bread crumbs to coat.'),
('3d75a7b2-72cf-494c-87f8-921cd4e8c7af', 'e1cbf24e-ee1a-4d37-84b8-64e6a2690d80', 4, 'Bake in the preheated oven until golden on top and chicken is cooked through, about 20 minutes.'),
('2049a288-7d61-4435-89e7-24d23b48f6bc', '1f480694-8dd1-49b1-8816-3fc842ba3f95', 1, 'Fill an Irish coffee glass with hot water; let sit for a few minutes until glass is hot, then discard water.'),
('4199b77e-714f-4118-82b9-dace590b0012', '1f480694-8dd1-49b1-8816-3fc842ba3f95', 2, 'Pour honey and bourbon into the preheated glass and top with 3/4 cup hot water. Garnish with a lemon twist.'),
('88e45b78-9d10-4305-89b9-f17f2182882d', 'efc3ca15-8ddb-4667-8314-0fb194e241fa', 1, 'Combine apples, orange juice, white sugar, 1 teaspoon vanilla, nutmeg, and salt in a small saucepan. Bring to a boil. Reduce heat to medium-low and cook, covered, stirring occasionally, until apples are tender and mixture thickens, 3 to 5 minutes. Stir in orange zest. Spread filling on a plate and let cool completely.'),
('655ce80a-fca8-4b3c-8786-eb8ecfcbfcf9', 'efc3ca15-8ddb-4667-8314-0fb194e241fa', 2, 'Preheat oven to 200 dergrees F (93 degrees C). Pour oil to a depth of 3/4 inch in a deep 10-inch skillet; heat to between 350 and 375 degrees F (180 to 190 degrees C). You''ll need about 1 quart oil.'),
('fc6efd9d-c8b6-4115-8cd8-47f3b5ce6ec3', 'efc3ca15-8ddb-4667-8314-0fb194e241fa', 3, 'Meanwhile, arrange 1 egg roll wrapper on a work surface with 1 corner pointed toward you like a diamond. Spread 1 tablespoon chocolate-hazelnut spread and 3 tablespoons apple filling in the center bottom half of wrapper. Fold bottom corner over filling, tucking it under on other side. Fold side corners over filling, forming an envelope shape. Roll egg roll toward remaining corner. Moisten top corner with water; press firmly to seal. Place on a parchment paper-lined baking sheet. Repeat with remaining wrappers, chocolate-hazelnut spread, and apple filling.'),
('5777b8de-8485-4bf4-8a35-786ddc7af7f0', 'efc3ca15-8ddb-4667-8314-0fb194e241fa', 4, 'Working in batches, fry egg rolls, turning occasionally, until golden brown, 3 to 5 minutes. Drain on a paper towel-line plate. Transfer to prepared baking sheet; keep warm in oven while frying remaining egg rolls.'),
('a5b766c3-cfbe-4854-8882-faf73c0592c1', 'efc3ca15-8ddb-4667-8314-0fb194e241fa', 5, 'Beat cream, powdered sugar, cocoa powder, and remaining 1/2 teaspoon vanilla in a medium bowl with an electric mixer at medium speed until stiff peaks form.'),
('6b127e70-1131-4d78-82f3-a32ef4774b6c', 'efc3ca15-8ddb-4667-8314-0fb194e241fa', 6, 'Top warm egg rolls with whipped cream and hazelnuts. Garnish with chocolate shavings and additional orange zest.'),
('59680089-ca7f-4f89-860d-db88c658bd73', 'd996ae72-200a-49ac-8985-3c511cf6ba38', 1, 'Pour pineapple chunks with juice into a saucepan. Mix in green bell pepper, brown sugar, cornstarch, soy sauce, and lemon juice; stir until sugar and cornstarch dissolve.'),
('2c803bee-4c71-424c-860a-9a3929ecf6c1', 'd996ae72-200a-49ac-8985-3c511cf6ba38', 2, 'Bring mixture to a boil; cook and stir until thickened, about 10 minutes.'),
('2043e475-1121-4c59-82fc-8338a6038059', 'd996ae72-200a-49ac-8985-3c511cf6ba38', 3, 'Place meatballs in a slow cooker; pour pineapple mixture over meatballs.'),
('80258222-7096-4721-8e27-0c07dffed244', 'd996ae72-200a-49ac-8985-3c511cf6ba38', 4, 'Cook on Medium for 2 hours, stirring every 30 minutes.');
insert into public.recipe_step_translations (step_id, locale, instruction) values
('88f65797-7f4e-4db5-8748-3de5f3270537', 'en', 'Gather all ingredients.'),
('88f65797-7f4e-4db5-8748-3de5f3270537', 'ko', '모든 재료를 준비하세요.'),
('b4a2b7f8-1a20-4f63-8189-cd4dda660dbc', 'en', 'Soak cedar planks for at least 1 hour in warm water. Soak longer if you have time.'),
('b4a2b7f8-1a20-4f63-8189-cd4dda660dbc', 'ko', '삼나무 판자를 따뜻한 물에 최소 1시간 동안 담가두세요. 시간이 있다면 더 오래 담가두세요.'),
('2fb53d46-e2ac-46a1-82f4-91a8f29bb3e0', 'en', 'Stir soy sauce, vegetable oil, rice vinegar, sesame oil, green onions, ginger, and garlic together in a shallow dish.'),
('2fb53d46-e2ac-46a1-82f4-91a8f29bb3e0', 'ko', '얕은 접시에 간장, 식물성 기름, 쌀식초, 참기름, 파, 생강, 마늘을 넣고 저어주세요.'),
('f9176c1b-3fb5-43ca-8500-8700e6857bba', 'en', 'Place salmon fillets in soy mixture and turn to coat. Cover and marinate for at least 15 minutes, or up to 1 hour refrigerated.'),
('f9176c1b-3fb5-43ca-8500-8700e6857bba', 'ko', '연어 필렛을 간장 혼합물에 넣고 뒤집어 코팅하세요. 덮어서 최소 15분간, 또는 냉장고에서 최대 1시간 동안 재워주세요.'),
('a8e2c8a6-05ad-455c-8b8b-b71821180174', 'en', 'Preheat an outdoor grill for medium heat. Place planks on the grill grate. Heat planks until they start to smoke and crackle just a little.'),
('a8e2c8a6-05ad-455c-8b8b-b71821180174', 'ko', '야외 그릴을 중간 불로 예열하세요. 그릴 격자 위에 판자를 놓으세요. 판자가 연기를 내고 약간 탁탁 소리를 낼 때까지 가열하세요.'),
('8d983fae-2167-429d-8b5a-39de0bcf7a60', 'en', 'Remove salmon from marinade and place on planks; discard marinade.'),
('8d983fae-2167-429d-8b5a-39de0bcf7a60', 'ko', '연어를 마리네이드에서 꺼내 판자 위에 놓으세요; 마리네이드는 버리세요.'),
('b992fa8e-f844-440b-8b53-cc32fcd565cf', 'en', 'Close grill cover. Grill salmon until it flakes easily with a fork, about 20 minutes; salmon will continue to cook after you remove it from the grill.'),
('b992fa8e-f844-440b-8b53-cc32fcd565cf', 'ko', '그릴 뚜껑을 닫으세요. 연어가 포크로 쉽게 부스러질 때까지 약 20분간 구우세요; 연어는 그릴에서 꺼낸 후에도 계속 익습니다.'),
('d73954cb-2ae3-431d-8d61-9b8a93db58e2', 'en', 'Combine vegetable broth, rinsed beans, diced tomatoes, onion, carrots, celery, garlic, sea salt, paprika, and black pepper in a multi-functional pressure cooker (such as Instant Pot). Close and lock the lid. Select high pressure according to manufacturer''s instructions; set the timer for 35 minutes. Allow 10 to 15 minutes for pressure to build.'),
('d73954cb-2ae3-431d-8d61-9b8a93db58e2', 'ko', '야채 육수, 헹군 콩, 깍둑썰기한 토마토, 양파, 당근, 셀러리, 마늘, 천일염, 파프리카, 후추를 다기능 압력솥(인스턴트 팟 등)에 넣습니다. 뚜껑을 닫고 잠급니다. 제조사 지침에 따라 고압을 선택하고 타이머를 35분으로 설정합니다. 압력이 형성되는 데 10~15분 정도 걸립니다.'),
('1e1b50b9-852f-4578-8929-d7c757b55209', 'en', 'Release pressure using the natural-release method according to manufacturer''s instructions, about 10 minutes. Complete releasing pressure carefully using the quick-release method according to manufacturer''s instructions, about 5 minutes. Unlock and remove the lid.'),
('1e1b50b9-852f-4578-8929-d7c757b55209', 'ko', '제조사 지침에 따라 자연 압력 해제 방법을 사용하여 압력을 해제합니다(약 10분). 제조사 지침에 따라 빠른 압력 해제 방법을 사용하여 조심스럽게 압력 해제를 완료합니다(약 5분). 뚜껑을 열고 제거합니다.'),
('6a738b2f-b792-441f-8e67-1900b4c87963', 'en', 'Preheat oven to 350 degrees F (175 degrees C).'),
('6a738b2f-b792-441f-8e67-1900b4c87963', 'ko', '오븐을 350도 F (175도 C)로 예열합니다.'),
('a8e4299f-dc35-498f-8cb2-698737676cc9', 'en', 'In a large bowl, cream butter and confectioners'' sugar until light and fluffy. Stir together flour and baking powder; blend into butter mixture. Pat into a 9 inch pie plate.'),
('a8e4299f-dc35-498f-8cb2-698737676cc9', 'ko', '큰 볼에 버터와 슈가파우더를 넣고 가볍고 부드러워질 때까지 섞습니다. 중력분과 베이킹파우더를 함께 체쳐서 버터 혼합물에 넣고 섞습니다. 9인치 파이 팬에 눌러 담습니다.'),
('5120dddf-6da9-4045-808b-edcc8a54b121', 'en', 'Bake in preheated oven for 12 to 15 minutes, or until edges are lightly browned.'),
('5120dddf-6da9-4045-808b-edcc8a54b121', 'ko', '예열된 오븐에서 12~15분간 또는 가장자리가 살짝 갈색이 될 때까지 굽습니다.'),
('939d311f-9845-4ce5-898a-bc2938b7a2de', 'en', 'Preheat the oven to 350 degrees F (180 degrees C).'),
('939d311f-9845-4ce5-898a-bc2938b7a2de', 'ko', '오븐을 화씨 350도(섭씨 180도)로 예열합니다.'),
('cff79f93-4a88-4bcf-8d7a-819d125cb4d1', 'en', 'Place naan breads on a baking sheet; brush each with olive oil. Sprinkle evenly with garlic powder and dried dill. Top each naan with half of tzatziki sauce, 1/2 cup chicken, and half of feta cheese.'),
('cff79f93-4a88-4bcf-8d7a-819d125cb4d1', 'ko', '베이킹 시트에 난 브레드를 놓고 각각 올리브 오일을 바릅니다. 마늘 가루와 건조 딜을 고르게 뿌립니다. 각 난에 차치키 소스 절반, 닭고기 1/2컵, 페타 치즈 절반을 올립니다.'),
('dfb6dbe6-3bdb-4df2-8eca-fa7dc2b38d1f', 'en', 'Bake in the preheated oven until cheese is bubbly and the edges are nice and brown, about 7 minutes. Remove from the oven and top with red onion, tomatoes, and cucumber. Serve warm.'),
('dfb6dbe6-3bdb-4df2-8eca-fa7dc2b38d1f', 'ko', '예열된 오븐에서 치즈가 부글부글 끓고 가장자리가 갈색으로 잘 구워질 때까지 약 7분간 굽습니다. 오븐에서 꺼내 적양파, 토마토, 오이를 올립니다. 따뜻할 때 제공합니다.'),
('5f45abea-119c-4776-8b5c-19e87f0ce61c', 'en', 'Gather all ingredients. Preheat the oven to 350 degrees F (175 degrees C). Line a baking sheet with aluminum foil and lightly coat with cooking spray.'),
('5f45abea-119c-4776-8b5c-19e87f0ce61c', 'ko', '모든 재료를 준비합니다. 오븐을 350도 F (175도 C)로 예열합니다. 베이킹 시트에 알루미늄 포일을 깔고 쿠킹 스프레이를 가볍게 뿌립니다.'),
('73e6c9b7-2eaf-489d-82b6-be6aa9129d0a', 'en', 'Combine walnuts, pecans, almonds, and cashews in a large bowl. Add salt, black pepper, cumin, and cayenne; toss to coat.'),
('73e6c9b7-2eaf-489d-82b6-be6aa9129d0a', 'ko', '큰 볼에 호두, 피칸, 아몬드, 캐슈너트를 넣습니다. 소금, 후추, 커민, 카이엔 페퍼를 넣고 잘 섞어 코팅하기 합니다.'),
('59d9b1da-ba0d-41a2-8c0b-89c73fc3a69a', 'en', 'Heat sugar, water, and butter in a small saucepan over medium heat. Cook until butter is melted and sugar is dissolved, about 1 minute.'),
('59d9b1da-ba0d-41a2-8c0b-89c73fc3a69a', 'ko', '작은 냄비에 설탕, 물, 버터를 넣고 중불로 가열합니다. 버터가 녹고 설탕이 녹을 때까지 약 1분간 끓이기 합니다.'),
('a0a852b5-9b84-4af7-87ee-a6b83629a5a8', 'en', 'Slowly pour butter mixture over nuts and stir to coat.'),
('a0a852b5-9b84-4af7-87ee-a6b83629a5a8', 'ko', '버터 혼합물을 견과류 위에 천천히 부어 코팅하기 합니다.'),
('00a86926-901a-4415-8aaf-9a730fca44ce', 'en', 'Transfer nuts to the prepared baking sheet and spread into a single layer.'),
('00a86926-901a-4415-8aaf-9a730fca44ce', 'ko', '견과류를 준비된 베이킹 시트로 옮기고 단일 층으로 펼칩니다.'),
('597c17b4-464f-4a02-8d88-324cda0283d1', 'en', 'Bake nuts in the preheated oven for 10 minutes. Stir nuts to coat with warm syrup; spread out in a single layer. Return to the oven and bake until nuts are sticky and roasted, about 6 more minutes. Allow to cool before serving.'),
('597c17b4-464f-4a02-8d88-324cda0283d1', 'ko', '예열된 오븐에서 견과류를 10분간 굽기 합니다. 따뜻한 시럽으로 견과류를 코팅하기 위해 저어주고 단일 층으로 펼칩니다. 오븐에 다시 넣고 견과류가 끈적하고 구워질 때까지 약 6분 더 굽기 합니다. 서빙하기 전에 식힙니다.'),
('0530fa91-eaf5-4f33-86f7-4cea24784102', 'en', 'Allow to cool before serving.'),
('0530fa91-eaf5-4f33-86f7-4cea24784102', 'ko', '서빙하기 전에 식힙니다.'),
('79aeb81d-7833-45de-82e7-c62de7ad6c2f', 'en', 'Gather all ingredients. Preheat the oven to 375 degrees F (190 degrees C). Line a baking sheet with parchment paper or a silicone baking mat.'),
('79aeb81d-7833-45de-82e7-c62de7ad6c2f', 'ko', '모든 재료를 준비합니다. 오븐을 375도F(190도C)로 예열합니다. 베이킹 시트에 유산지나 실리콘 베이킹 매트를 깔아줍니다.'),
('8e61bf49-51f8-43f1-8226-ae6a9417b61a', 'en', 'Whisk all-purpose flour, whole wheat flour, oats, salt, baking soda, and baking powder together in a large bowl. Cut butter into flour mixture using a pastry blender until mixture resembles coarse crumbs.'),
('8e61bf49-51f8-43f1-8226-ae6a9417b61a', 'ko', '큰 볼에 중력분, 통밀가루, 오트, 소금, 베이킹 소다, 베이킹 파우더를 함께 휘젓습니다. 페이스트리 블렌더를 사용하여 버터를 밀가루 혼합물에 섞어 거친 부스러기 같은 질감이 될 때까지 자릅니다.'),
('25ee8413-0489-427e-84a7-85fa45641a7d', 'en', 'Beat buttermilk, egg, honey, and orange zest together in a medium bowl. Pour buttermilk mixture, currants, and raisins into flour-butter mixture; stir with a wooden spoon until a wet, sticky dough comes together.'),
('25ee8413-0489-427e-84a7-85fa45641a7d', 'ko', '중간 크기 볼에 버터밀크, 달걀, 꿀, 오렌지 제스트를 함께 휘젓습니다. 버터밀크 혼합물, 커런트, 건포도를 밀가루-버터 혼합물에 붓고 나무 스푼으로 젖고 끈적한 반죽이 뭉쳐질 때까지 저어주다.'),
('25af0307-4e0e-42fd-8056-f77a2252ab27', 'en', 'Turn dough out onto a well-floured work surface; press dough together into a ball and cut into 2 equal pieces. Form each into a smooth, round loaf.'),
('25af0307-4e0e-42fd-8056-f77a2252ab27', 'ko', '반죽을 밀가루를 충분히 뿌린 작업대 위에 옮깁니다. 반죽을 눌러 공 모양으로 만들고 2등분합니다. 각각을 매끄럽고 둥근 덩어리로 만듭니다.'),
('ace323fa-08ac-4651-80a0-30e62ff57b63', 'en', 'Transfer to the prepared baking sheet and let rest for 15 minutes. Cut a 1/2-inch-deep "X" into the top of each loaf using a serrated knife.'),
('ace323fa-08ac-4651-80a0-30e62ff57b63', 'ko', '준비한 베이킹 시트로 옮기고 15분간 휴지시킵니다. 톱니 칼을 사용하여 각 덩어리 윗면에 ½인치 깊이의 "X" 자를 냅니다.'),
('a46cf066-0a45-4aef-8b51-d3bf32bacbfe', 'en', 'Bake in the preheated oven until golden brown and fragrant, about 45 minutes. Transfer loaves to a wire rack to cool completely before slicing.'),
('a46cf066-0a45-4aef-8b51-d3bf32bacbfe', 'ko', '예열된 오븐에서 황금빛 갈색이 나고 향이 날 때까지 약 45분간 굽기. 완전히 식히기 위해 덩어리들을 와이어 랙으로 옮긴 후 슬라이스합니다.'),
('ffb8c320-9d0a-4b84-8516-dd28eba939f2', 'en', 'Enjoy!'),
('ffb8c320-9d0a-4b84-8516-dd28eba939f2', 'ko', '맛있게 드세요!'),
('72d49eb6-a1ed-458e-86dc-4aeffefbb562', 'en', 'Place garlic cloves in a medium bowl, first cutting the large cloves in half. Mix in the red bell pepper.'),
('72d49eb6-a1ed-458e-86dc-4aeffefbb562', 'ko', '마늘을 중간 크기 볼에 넣고, 큰 마늘은 반으로 자릅니다. 빨간 파프리카를 넣고 섞습니다.'),
('67bced14-5d75-45c9-862c-3281dbbdab92', 'en', 'In a large saucepan over medium high heat, place the distilled white vinegar and white sugar. Wrap ground dry mustard and celery seed in a spice bag, and place in the liquid mixture. Bring to a boil. Boil 5 minutes. Stir in garlic and pepper. Continue boiling 5 minutes. Remove from heat and discard spice bag.'),
('67bced14-5d75-45c9-862c-3281dbbdab92', 'ko', '큰 냄비에 증류 백식초와 백설탕을 넣고 중강불로 가열합니다. 겨자 가루와 셀러리 씨를 향신료 주머니에 싸서 액체 혼합물에 넣습니다. 끓입니다. 5분간 끓입니다. 마늘과 파프리카를 넣고 저어주세요. 5분간 계속 끓입니다. 불에서 내려 향신료 주머니를 제거합니다.'),
('d8b7bfb4-78a8-41bf-87e1-0f5abc6c0649', 'en', 'Place garlic and peppers in sterile containers to within 1 inch of the top. Fill with remaining liquid to within 1/4 inch from the top. Seal and store in the refrigerator approximately three weeks before serving.'),
('d8b7bfb4-78a8-41bf-87e1-0f5abc6c0649', 'ko', '마늘과 파프리카를 멸균 용기에 상단에서 1인치 아래까지 넣습니다. 남은 액체를 상단에서 1/4인치 아래까지 채웁니다. 밀봉하여 냉장고에 보관하고 서빙하기 전 약 3주 정도 숙성시킵니다.'),
('39971a06-f72e-4134-8784-42ffd034b74f', 'en', 'Combine brown sugar, white sugar, butter, corn syrup, cream, milk and vanilla in a medium saucepan over medium heat. Heat, stirring occasionally, to 250 to 265 degrees F (121 to 129 degrees C), or until a small amount of syrup dropped into cold water forms a rigid ball. Pour into an 8x8 inch pan. Let cool before cutting.'),
('39971a06-f72e-4134-8784-42ffd034b74f', 'ko', '중간 크기 냄비에 흑설탕, 백설탕, 버터, 옥수수 시럽, 크림, 우유, 바닐라를 넣고 중불로 가열합니다. 가끔 저어주면서 화씨 250~265도(섭씨 121~129도)까지 가열하거나 시럽을 찬물에 조금 떨어뜨렸을 때 단단한 공 모양이 형성될 때까지 가열합니다. 8x8인치 팬에 부어줍니다. 자르기 전에 식혀줍니다.'),
('901706ea-ca6e-4ed7-8432-b9cb685de294', 'en', 'Gather all ingredients.'),
('901706ea-ca6e-4ed7-8432-b9cb685de294', 'ko', '모든 재료를 준비하세요.'),
('f3380d15-0133-443c-80ab-2a3b8001e31c', 'en', 'Preheat the oven to 350 degrees F (175 degrees C).'),
('f3380d15-0133-443c-80ab-2a3b8001e31c', 'ko', '오븐을 350도F(175도C)로 예열하세요.'),
('125bee52-096f-4006-8e61-9347d83d1ce5', 'en', 'Remove and discard giblets.'),
('125bee52-096f-4006-8e61-9347d83d1ce5', 'ko', '내장을 제거하고 버리세요.'),
('cd93df6a-347a-4d34-8ea4-489743a410b4', 'en', 'Rinse turkey and pat dry.'),
('cd93df6a-347a-4d34-8ea4-489743a410b4', 'ko', '칠면조를 헹구고 물기를 닦아내세요.'),
('160c5f82-b48f-4641-892f-4418b09642c9', 'en', 'Season turkey with salt and pepper.'),
('160c5f82-b48f-4641-892f-4418b09642c9', 'ko', '칠면조에 소금과 후추로 간을 하세요.'),
('96db6a92-9e6d-47cb-8189-1feaeef29307', 'en', 'Sprinkle the bottom of the turkey bag with flour.'),
('96db6a92-9e6d-47cb-8189-1feaeef29307', 'ko', '칠면조 백 바닥에 밀가루를 뿌리세요.'),
('109345b0-c9b9-4fa4-879f-4405774385c8', 'en', 'Place turkey in the bag and add celery and onions.'),
('109345b0-c9b9-4fa4-879f-4405774385c8', 'ko', '칠면조를 백에 넣고 셀러리와 양파를 추가하세요.'),
('15153eb5-d1df-45ec-80f9-66736112edda', 'en', 'Seal the bag and transfer into a roasting pan; poke several holes in the bag with a fork.'),
('15153eb5-d1df-45ec-80f9-66736112edda', 'ko', '백을 밀봉하고 로스팅 팬으로 옮긴 후, 포크로 백에 여러 개의 구멍을 내세요.'),
('21ea6e5b-2600-4f2c-8cc0-cd9fa7a863d2', 'en', 'Bake in the preheated oven until turkey is cooked and the juices run clear, about 3 to 3 1/2 hours. An instant-read thermometer inserted into the thigh meat should read 180 degrees F (85 degrees C).'),
('21ea6e5b-2600-4f2c-8cc0-cd9fa7a863d2', 'ko', '예열된 오븐에서 칠면조가 익고 육즙이 맑게 나올 때까지 약 3~3시간 30분 동안 구우세요. 허벅지 살에 꽂은 즉석 온도계가 180도F(85도C)를 나타내야 합니다.'),
('91c4bd6a-4482-407d-8e64-e8e4bfa1678c', 'en', 'Enjoy!'),
('91c4bd6a-4482-407d-8e64-e8e4bfa1678c', 'ko', '맛있게 드세요!'),
('8247e494-6ee7-4d50-88bb-cedaddfdbba1', 'en', 'Gather all ingredients.'),
('8247e494-6ee7-4d50-88bb-cedaddfdbba1', 'ko', '모든 재료를 준비하세요.'),
('a8619e92-836a-49a8-8d51-5d39cc4c5667', 'en', 'Preheat the oven to 425 degrees F (220 degrees C). Position rack in upper third of the oven. Grease a baking sheet.'),
('a8619e92-836a-49a8-8d51-5d39cc4c5667', 'ko', '오븐을 425도 F (220도 C)로 예열하세요. 오븐 상단 3분의 1 위치에 랙을 놓으세요. 베이킹 시트에 기름을 바르세요.'),
('c195ee26-3839-4dd9-877c-a272b2a98002', 'en', 'Peel sweet potatoes and cut into 1x3-inch wedges. Place wedges and soybean oil in a large bowl; toss lightly. Sprinkle with salt, pepper, garlic powder, and paprika.'),
('c195ee26-3839-4dd9-877c-a272b2a98002', 'ko', '고구마 껍질을 벗기고 1x3인치 쐐기 모양으로 자르세요. 큰 볼에 쐐기 모양 고구마와 대두유를 넣고 가볍게 버무리세요. 소금, 후추, 마늘 가루, 파프리카 가루를 뿌리세요.'),
('7bdd56ab-662a-4fa1-8636-a246ca497515', 'en', 'Arrange potatoes in a single layer on the prepared baking sheet, being sure not to overcrowd. Bake, turning occasionally, until tender and golden brown, 18 to 24 minutes. Cool 5 minutes before serving.'),
('7bdd56ab-662a-4fa1-8636-a246ca497515', 'ko', '준비한 베이킹 시트에 고구마를 겹치지 않게 한 겹으로 배열하세요. 부드럽고 황금빛 갈색이 될 때까지 가끔 뒤집어가며 18~24분간 구우세요. 서빙하기 전 5분간 식히세요.'),
('8f76469f-a3a0-4a35-8ee5-3949026fa403', 'en', 'Preheat the oven to 350 degrees F (175 degrees C).'),
('8f76469f-a3a0-4a35-8ee5-3949026fa403', 'ko', '오븐을 350도(175도 C)로 예열합니다.'),
('8f795e48-52b9-4730-8f58-67ac619c3be5', 'en', 'Spread peach slices evenly in the bottom of a 9x13-inch baking dish. Stir water and sugar together in a small bowl until dissolved; pour mixture over peaches. Sprinkle cinnamon over peaches, then cake mix. Top cake mix with pats of cream cheese, then butter.'),
('8f795e48-52b9-4730-8f58-67ac619c3be5', 'ko', '9x13인치 베이킹 접시 바닥에 복숭아 슬라이스를 고르게 펼칩니다. 작은 볼에 물과 설탕을 넣고 녹을 때까지 저어준 후 복숭아 위에 붓습니다. 복숭아 위에 계피를 뿌린 다음 케이크 믹스를 뿌립니다. 케이크 믹스 위에 크림치즈 조각을 올리고 그 위에 버터를 올립니다.'),
('798801b4-362c-4279-8f3e-36a9ca5c9d88', 'en', 'Bake in the preheated oven until golden, about 45 minutes.'),
('798801b4-362c-4279-8f3e-36a9ca5c9d88', 'ko', '예열된 오븐에서 황금빛이 될 때까지 약 45분간 굽습니다.'),
('047755b9-751d-4236-81b1-d08f208be242', 'en', 'Preheat the oven to 350 degrees F (175 degrees C).'),
('047755b9-751d-4236-81b1-d08f208be242', 'ko', '오븐을 350도 F (175도 C)로 예열합니다.'),
('98a2922f-2e6a-42d9-81cf-168a3ef5e995', 'en', 'In a medium bowl, mix together the green onions and cream cheese . Stuff mushroom caps with the cheese mixture. Wrap each mushroom with a half-slice of bacon, and secure with toothpicks. Place on a baking sheet.'),
('98a2922f-2e6a-42d9-81cf-168a3ef5e995', 'ko', '중간 크기 볼에 쪽파와 크림치즈를 섞습니다. 버섯 갓에 치즈 혼합물을 채웁니다. 각 버섯을 베이컨 반 조각으로 감싸고 이쑤시개로 고정합니다. 베이킹 시트에 올립니다.'),
('51346f91-b8b7-4f70-8bf7-ad3db2f14938', 'en', 'Bake for 20 minutes in the preheated oven, until the bacon is cooked through.'),
('51346f91-b8b7-4f70-8bf7-ad3db2f14938', 'ko', '예열된 오븐에서 베이컨이 완전히 익을 때까지 20분간 굽습니다.'),
('d01ae135-83f9-49b0-801f-92425cbc80ea', 'en', 'Melt butter in a skillet over medium heat. Cook onion and poblano pepper until softened, about 5 minutes. Transfer mixture to a plate. Add ground beef and chorizo to the skillet. Cook, stirring often to break up meat, until browned and crumbly, 5 to 7 minutes. Add enchilada seasoning and tomato powder. Add water, ketchup, and Worcestershire sauce. Return cooked onion mixture to the skillet. Simmer until flavors combine, about 5 minutes more.'),
('d01ae135-83f9-49b0-801f-92425cbc80ea', 'ko', '중불로 스킬렛에 버터를 녹입니다. 양파와 포블라노 고추를 넣고 부드러워질 때까지 약 5분간 익힙니다. 혼합물을 접시에 옮깁니다. 스킬렛에 간 쇠고기와 초리조를 넣습니다. 고기가 부서지도록 자주 저어주면서 갈색이 되고 부슬부슬해질 때까지 5~7분간 익힙니다. 엔칠라다 시즈닝과 토마토 파우더를 넣습니다. 물, 케첩, 우스터셔 소스를 넣습니다. 익힌 양파 혼합물을 다시 스킬렛에 넣습니다. 맛이 어우러질 때까지 약 5분 더 약불로 끓입니다.'),
('dc44adc0-c419-4df4-81d2-5f96621386c9', 'en', 'Serve meat mixture on toasted buns topped with Oaxaca cheese and avocado.'),
('dc44adc0-c419-4df4-81d2-5f96621386c9', 'ko', '구운 번 위에 고기 혼합물을 올리고 오악사카 치즈와 아보카도를 올려 제공합니다.'),
('9d430237-8b2e-4052-8e95-46c33298306b', 'en', 'Place Hatch chiles directly on the grates of a gas stove over medium heat. Cook, flipping with tongs occasionally, until blackened and charred, about 5 minutes. Place in a sealed plastic bag and allow to cool, 7 to 8 minutes. Peel off charred skins, remove seeds, and slice chiles.'),
('9d430237-8b2e-4052-8e95-46c33298306b', 'ko', '해치 칠리를 가스레인지 화구에 직접 올려 중불로 가열하다. 집게로 가끔 뒤집어가며 겉이 까맣게 그을릴 때까지 약 5분간 굽기. 밀봉된 비닐봉지에 넣고 7~8분간 식히다. 그을린 껍질을 벗기고 씨를 제거한 후 칠리를 슬라이스하다.'),
('0fd70de3-e5b3-4407-85c7-020777d64638', 'en', 'Slice potato using a mandoline.'),
('0fd70de3-e5b3-4407-85c7-020777d64638', 'ko', '만돌린을 사용하여 감자를 슬라이스하다.'),
('56357ba9-f9bc-4b54-8884-c6af6dc63dc3', 'en', 'Heat oil in a large skillet over medium-high heat until shimmering. Add potato slices and fry undisturbed until starting to brown and soften, 8 to 12 minutes. Add onion slices and chiles. Season with seasoned salt and black pepper. Stir to combine. Cook until onions are translucent and potatoes are fully softened and browned on the second side, 5 to 8 minutes.'),
('56357ba9-f9bc-4b54-8884-c6af6dc63dc3', 'ko', '큰 팬에 기름을 두르고 중강불로 기름이 반짝일 때까지 가열하다. 감자 슬라이스를 넣고 갈색이 나고 부드러워지기 시작할 때까지 건드리지 않고 8~12분간 튀기다. 양파 슬라이스와 칠리를 넣다. 시즈닝 소금과 흑후추로 간하다. 저어주다. 양파가 투명해지고 감자가 완전히 부드러워지며 반대쪽 면이 갈색이 될 때까까지 5~8분간 익히다.'),
('e5bdd60b-358d-41f4-89ba-5975e78f17c0', 'en', 'Combine onion, vinegar, olive oil, parsley, brown sugar, garlic, salt, and dry mustard in a medium saucepan. Bring to a boil. Reduce heat, stir in mushrooms, and simmer for 10 to 12 minutes, stirring occasionally.'),
('e5bdd60b-358d-41f4-89ba-5975e78f17c0', 'ko', '중간 크기 냄비에 양파, 식초, 올리브 오일, 파슬리, 황설탕, 마늘, 소금, 건조 겨자를 넣습니다. 끓입니다. 불을 줄이고 버섯을 넣어 저어주며 10~12분간 약불로 끓입니다.'),
('f521cd76-682d-428a-846d-7b510e8cbe9a', 'en', 'Transfer mushroom mixture to sterile containers and chill in the refrigerator until serving.'),
('f521cd76-682d-428a-846d-7b510e8cbe9a', 'ko', '버섯 혼합물을 소독된 용기에 옮겨 담고 서빙할 때까지 냉장고에서 차게 보관합니다.'),
('c489fcce-b3a3-4698-80c3-5582a9e4f279', 'en', 'Gather the ingredients.'),
('c489fcce-b3a3-4698-80c3-5582a9e4f279', 'ko', '재료를 준비합니다.'),
('74b31868-70b3-4202-8d6b-45ed04192745', 'en', 'Preheat an outdoor grill for high heat and lightly oil the grate.'),
('74b31868-70b3-4202-8d6b-45ed04192745', 'ko', '야외 그릴을 고온으로 예열하고 그릴판에 기름을 가볍게 바릅니다.'),
('14f24990-3483-4663-806e-17243d5f4816', 'en', 'Combine ground beef, Worcestershire sauce, liquid smoke, and garlic powder in a medium bowl; lightly mix until just combined.'),
('14f24990-3483-4663-806e-17243d5f4816', 'ko', '중간 크기 볼에 간 소고기, 우스터 소스, 리퀴드 스모크, 마늘 가루를 넣고 가볍게 섞어 재료가 겨우 섞일 정도로만 합칩니다.'),
('30258334-092b-426c-89bd-163dbb4e4b31', 'en', 'With minimal handling, form mixture into three patties.'),
('30258334-092b-426c-89bd-163dbb4e4b31', 'ko', '최소한으로 만지면서 혼합물을 세 개의 패티로 만듭니다.'),
('2017b9bf-8012-4ca5-85b7-1328330701cc', 'en', 'Brush oil onto both sides of each patty, then season with salt.'),
('2017b9bf-8012-4ca5-85b7-1328330701cc', 'ko', '각 패티의 양면에 오일을 바르고 소금으로 간합니다.'),
('c83c3bb2-b7df-4a29-8fb0-db3a5d986221', 'en', 'Cook patties on the preheated grill until no longer pink in the center, about 5 minutes per side. An instant-read thermometer inserted into the center should read at least 160 degrees F (70 degrees C).'),
('c83c3bb2-b7df-4a29-8fb0-db3a5d986221', 'ko', '예열된 그릴에서 패티 중앙이 더 이상 분홍색이 아닐 때까지 한 면당 약 5분씩 익힙니다. 중앙에 꽂은 즉석 온도계가 최소 화씨 160도(섭씨 70도)를 나타내야 합니다.'),
('7ed33c9a-bf75-4ede-8931-90fc220f4f4d', 'en', 'Gather all ingredients. Preheat the oven to 425 degrees F (220 degrees C).'),
('7ed33c9a-bf75-4ede-8931-90fc220f4f4d', 'ko', '모든 재료를 준비합니다. 오븐을 425도 F (220도 C)로 예열합니다.'),
('a1b16812-e004-4ef2-81a6-e62e85798f8a', 'en', 'Mix mayonnaise and Parmesan cheese together in a medium bowl until well combined.'),
('a1b16812-e004-4ef2-81a6-e62e85798f8a', 'ko', '중간 크기의 볼에 마요네즈와 파마산 치즈를 잘 섞일 때까지 섞습니다.'),
('6b199f73-2c4d-4533-8966-9971e95ff250', 'en', 'Arrange chicken breasts on a baking sheet. Evenly top with mayonnaise mixture, then sprinkle with bread crumbs to coat.'),
('6b199f73-2c4d-4533-8966-9971e95ff250', 'ko', '베이킹 시트에 닭 가슴살을 배열합니다. 마요네즈 혼합물을 고르게 올린 다음 빵가루를 뿌려 코팅합니다.'),
('3d75a7b2-72cf-494c-87f8-921cd4e8c7af', 'en', 'Bake in the preheated oven until golden on top and chicken is cooked through, about 20 minutes.'),
('3d75a7b2-72cf-494c-87f8-921cd4e8c7af', 'ko', '예열된 오븐에서 윗면이 황금빛이 되고 닭고기가 완전히 익을 때까지 약 20분 동안 굽습니다.'),
('2049a288-7d61-4435-89e7-24d23b48f6bc', 'en', 'Fill an Irish coffee glass with hot water; let sit for a few minutes until glass is hot, then discard water.'),
('2049a288-7d61-4435-89e7-24d23b48f6bc', 'ko', '아이리시 커피 잔에 뜨거운 물을 채우고 몇 분간 두어 잔이 뜨거워지면 물을 버립니다.'),
('4199b77e-714f-4118-82b9-dace590b0012', 'en', 'Pour honey and bourbon into the preheated glass and top with 3/4 cup hot water. Garnish with a lemon twist.'),
('4199b77e-714f-4118-82b9-dace590b0012', 'ko', '예열된 잔에 꿀과 버번을 붓고 뜨거운 물 ¾ 컵을 올립니다. 레몬 트위스트로 장식합니다.'),
('88e45b78-9d10-4305-89b9-f17f2182882d', 'en', 'Combine apples, orange juice, white sugar, 1 teaspoon vanilla, nutmeg, and salt in a small saucepan. Bring to a boil. Reduce heat to medium-low and cook, covered, stirring occasionally, until apples are tender and mixture thickens, 3 to 5 minutes. Stir in orange zest. Spread filling on a plate and let cool completely.'),
('88e45b78-9d10-4305-89b9-f17f2182882d', 'ko', '사과, 오렌지 주스, 백설탕, 바닐라 1 티스푼, 육두구, 소금을 작은 냄비에 넣고 섞습니다. 끓이기 시작하면 중약불로 줄이고 뚜껑을 덮은 채로 가끔 저어주면서 사과가 부드러워지고 혼합물이 걸쭉해질 때까지 3~5분간 익힙니다. 오렌지 제스트를 넣고 저어줍니다. 필링을 접시에 펼치고 완전히 식힙니다.'),
('655ce80a-fca8-4b3c-8786-eb8ecfcbfcf9', 'en', 'Preheat oven to 200 dergrees F (93 degrees C). Pour oil to a depth of 3/4 inch in a deep 10-inch skillet; heat to between 350 and 375 degrees F (180 to 190 degrees C). You''ll need about 1 quart oil.'),
('655ce80a-fca8-4b3c-8786-eb8ecfcbfcf9', 'ko', '오븐을 화씨 200도(섭씨 93도)로 예열합니다. 깊이 10인치 프라이팬에 기름을 3/4인치 깊이로 붓고 화씨 350~375도(섭씨 180~190도)로 가열합니다. 약 1 쿼트의 기름이 필요합니다.'),
('fc6efd9d-c8b6-4115-8cd8-47f3b5ce6ec3', 'en', 'Meanwhile, arrange 1 egg roll wrapper on a work surface with 1 corner pointed toward you like a diamond. Spread 1 tablespoon chocolate-hazelnut spread and 3 tablespoons apple filling in the center bottom half of wrapper. Fold bottom corner over filling, tucking it under on other side. Fold side corners over filling, forming an envelope shape. Roll egg roll toward remaining corner. Moisten top corner with water; press firmly to seal. Place on a parchment paper-lined baking sheet. Repeat with remaining wrappers, chocolate-hazelnut spread, and apple filling.'),
('fc6efd9d-c8b6-4115-8cd8-47f3b5ce6ec3', 'ko', '한편, 에그롤 래퍼 1장을 작업대 위에 다이아몬드 모양처럼 한 모서리가 자신을 향하도록 놓습니다. 초콜릿-헤이즐넛 스프레드 1 테이블스푼과 사과 필링 3 테이블스푼을 래퍼 아래쪽 중앙 절반에 펼칩니다. 아래 모서리를 필링 위로 접어 반대편 아래로 넣습니다. 양쪽 모서리를 필링 위로 접어 봉투 모양을 만듭니다. 남은 모서리 쪽으로 에그롤을 말아줍니다. 윗 모서리에 물을 묻혀 단단히 눌러 밀봉합니다. 양피지를 깔은 베이킹 시트에 놓습니다. 남은 래퍼, 초콜릿-헤이즐넛 스프레드, 사과 필링으로 반복합니다.'),
('5777b8de-8485-4bf4-8a35-786ddc7af7f0', 'en', 'Working in batches, fry egg rolls, turning occasionally, until golden brown, 3 to 5 minutes. Drain on a paper towel-line plate. Transfer to prepared baking sheet; keep warm in oven while frying remaining egg rolls.'),
('5777b8de-8485-4bf4-8a35-786ddc7af7f0', 'ko', '배치로 나누어 에그롤을 가끔 뒤집어가며 황금빛 갈색이 될 때까지 3~5분간 튀깁니다. 키친타올을 깐 접시에서 기름을 뺍니다. 준비된 베이킹 시트로 옮기고 남은 에그롤을 튀기는 동안 오븐에서 따뜻하게 유지합니다.'),
('a5b766c3-cfbe-4854-8882-faf73c0592c1', 'en', 'Beat cream, powdered sugar, cocoa powder, and remaining 1/2 teaspoon vanilla in a medium bowl with an electric mixer at medium speed until stiff peaks form.'),
('a5b766c3-cfbe-4854-8882-faf73c0592c1', 'ko', '크림, 슈가파우더, 코코아 파우더, 남은 바닐라 1/2 티스푼을 중간 크기 볼에 넣고 전동 믹서로 중간 속도로 뻣뻣한 봉우리가 형성될 때까지 휘핑합니다.'),
('6b127e70-1131-4d78-82f3-a32ef4774b6c', 'en', 'Top warm egg rolls with whipped cream and hazelnuts. Garnish with chocolate shavings and additional orange zest.'),
('6b127e70-1131-4d78-82f3-a32ef4774b6c', 'ko', '따뜻한 에그롤에 휘핑 크림과 헤이즐넛을 올립니다. 초콜릿 조각과 추가 오렌지 제스트로 장식합니다.'),
('59680089-ca7f-4f89-860d-db88c658bd73', 'en', 'Pour pineapple chunks with juice into a saucepan. Mix in green bell pepper, brown sugar, cornstarch, soy sauce, and lemon juice; stir until sugar and cornstarch dissolve.'),
('59680089-ca7f-4f89-860d-db88c658bd73', 'ko', '파인애플 청크를 주스와 함께 냄비에 붓습니다. 청피망, 흑설탕, 옥수수 전분, 간장, 레몬즙을 넣고 설탕과 옥수수 전분이 녹을 때까지 저어줍니다.'),
('2c803bee-4c71-424c-860a-9a3929ecf6c1', 'en', 'Bring mixture to a boil; cook and stir until thickened, about 10 minutes.'),
('2c803bee-4c71-424c-860a-9a3929ecf6c1', 'ko', '혼합물을 끓이고, 걸쭉해질 때까지 약 10분간 익히면서 저어줍니다.'),
('2043e475-1121-4c59-82fc-8338a6038059', 'en', 'Place meatballs in a slow cooker; pour pineapple mixture over meatballs.'),
('2043e475-1121-4c59-82fc-8338a6038059', 'ko', '미트볼을 슬로우 쿠커에 넣고 파인애플 혼합물을 미트볼 위에 붓습니다.'),
('80258222-7096-4721-8e27-0c07dffed244', 'en', 'Cook on Medium for 2 hours, stirring every 30 minutes.'),
('80258222-7096-4721-8e27-0c07dffed244', 'ko', '중불에서 2시간 동안 익히며, 30분마다 저어줍니다.');
